"""Precomputed SigLIP 2 text anchors and zero-shot scoring for the five default AI tags.

Pure numpy (no onnxruntime): callers that only score stored embeddings
(such as reclassifying after tag edits) import this module instead of
``clip_classifier`` so ONNX Runtime and its Windows WMI probe stay unloaded.
"""

from __future__ import annotations

import base64
import math

import numpy as np

from .clip_model import CATEGORIES, EMBEDDING_DIM

# Precomputed text anchors of the five default tags (5 x 768 float32, L2-normalized).
_CATEGORY_EMBEDDINGS_B64 = ""
_CATEGORY_EMBEDDINGS: np.ndarray | None = None
# exp(logit_scale) of the upstream checkpoint google/siglip2-base-patch16-224
# (its logit_bias, -16.771724700927734, is replaced by the measured cuts below).
LOGIT_SCALE = math.exp(4.724453449249268)
# Measured on 1,180 photos of a real library, against the categories its owner
# had confirmed (tools/bench_clip.py --calibrate). With averaged prompts the
# upstream logit_bias (-16.77) leaves every raw score near 0, and all five
# anchors share most of their direction (cosine 0.90-0.96 to each other), so a
# photo is compared with each anchor relative to its mean similarity to all
# five. A tag applies from its cut below (precision 0.91 for 일러스트 and 0.96
# for 인물 on the confirmed photos); the score is shaped so that every tag's cut
# lands on ZERO_SHOT_THRESHOLD, the default threshold of all AI tags.
ZERO_SHOT_CUTS = (0.020, 0.011, 0.028, 0.012, 0.015)
ZERO_SHOT_THRESHOLD = 0.65
_THRESHOLD_LOGIT = math.log(ZERO_SHOT_THRESHOLD / (1.0 - ZERO_SHOT_THRESHOLD))


def get_category_embeddings() -> np.ndarray:
    """Return the precomputed (5, 768) normalized text anchors of the default tags."""
    global _CATEGORY_EMBEDDINGS
    if _CATEGORY_EMBEDDINGS is None:
        raw = base64.b64decode(_CATEGORY_EMBEDDINGS_B64)
        arr = np.frombuffer(raw, dtype=np.float32).reshape(len(CATEGORIES), EMBEDDING_DIM)
        _CATEGORY_EMBEDDINGS = arr
    return _CATEGORY_EMBEDDINGS


def zero_shot_probabilities(embeddings: np.ndarray) -> np.ndarray:
    """``(n, 5)`` independent sigmoid scores of stored features against the default tags."""
    matrix = np.asarray(embeddings, dtype=np.float32)
    if matrix.ndim == 1:
        matrix = matrix.reshape(1, -1)
    if matrix.ndim != 2 or matrix.shape[1] != EMBEDDING_DIM:
        return np.zeros((0, len(CATEGORIES)), dtype=np.float32)
    similarity = (matrix @ get_category_embeddings().T).astype(np.float64)
    relative = similarity - similarity.mean(axis=1, keepdims=True)
    logits = (relative - np.asarray(ZERO_SHOT_CUTS, dtype=np.float64)) * LOGIT_SCALE + _THRESHOLD_LOGIT
    return (1.0 / (1.0 + np.exp(-np.clip(logits, -60.0, 60.0)))).astype(np.float32)
